<script setup>
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';
import {Head,Link,useForm} from '@inertiajs/vue3';
const props=defineProps({document:Object,hash:String,preview:Boolean,readOnly:Boolean});
const dialog=ref(null);let overflow;
const form=useForm({context:props.document.context,version:props.document.version,hash:props.hash,terms:false,privacy:false,provider:false});
const role=computed(()=>({spaces:'Landlord',haul:'UV Owner',raketeer:'Raketeer'}[props.document.context]));
onMounted(()=>{overflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.value.showModal();});
onBeforeUnmount(()=>{dialog.value?.close();document.body.style.overflow=overflow;});
function submit(){if(!props.preview&&!props.readOnly&&!form.processing)form.post('/legal/accept',{preserveScroll:true});}
</script>
<template><Head title="Terms and privacy"/><main class="legal-background"><img src="/images/logos/Aadi_Color.png" alt="Aadi"/><h1>Know where you stand.</h1><p>Clear responsibilities. Informed choices.</p></main>
<dialog ref="dialog" class="legal-dialog" aria-labelledby="legal-title" @cancel.prevent><form @submit.prevent="submit"><header><p class="legal-kicker">AADI · ACCOUNT AGREEMENTS</p><h2 id="legal-title">{{ preview?'Draft for review':role?role+' responsibilities':'Before you get started' }}</h2><p>{{ preview?'This draft cannot be accepted or activated until the outstanding policy details are confirmed.':'Read the documents below before deciding whether to continue.' }}</p><small>Version {{ document.version }} · {{ document.effectiveDate||'Effective date not set' }}</small></header>
<div class="legal-content"><p v-if="document.operator.name"><strong>{{ document.operator.name }}</strong><br/>{{ document.operator.address }}<br/>{{ document.operator.email }}</p><section><h3>Terms and Conditions</h3><details v-for="section in document.terms" :key="section.title"><summary>{{ section.title }}</summary><p>{{ section.body }}</p></details></section><section><h3>Privacy Notice</h3><p>Acknowledging this notice does not give blanket consent for marketing or unrelated processing.</p><details v-for="section in document.privacy" :key="section.title"><summary>{{ section.title }}</summary><p>{{ section.body }}</p></details></section><section v-if="role"><h3>{{ role }} application</h3><article v-for="section in document.provider" :key="section.title"><h4>{{ section.title }}</h4><p>{{ section.body }}</p></article></section>
<div v-if="!preview&&!readOnly" class="legal-checks"><label><input v-model="form.terms" type="checkbox" required :disabled="form.processing"/>I agree to the Terms and Conditions.</label><label><input v-model="form.privacy" type="checkbox" required :disabled="form.processing"/>I acknowledge that the Privacy Notice explains how my information is handled.</label><label v-if="role"><input v-model="form.provider" type="checkbox" required :disabled="form.processing"/>I agree to the {{ role }} responsibilities and confirm I have authority to make this application.</label></div><div v-if="Object.keys(form.errors).length" role="alert" class="legal-errors"><p v-for="(error,key) in form.errors" :key="key">{{ error }}</p></div></div>
<footer><Link href="/" class="legal-link">{{ preview||readOnly?'Back to Aadi':'Not now — browse listings' }}</Link><button v-if="!preview&&!readOnly" type="submit" :disabled="form.processing">{{ form.processing?'Saving…':'Accept and continue' }}</button><Link v-if="!preview&&!readOnly" href="/logout" method="post" as="button" class="legal-logout">Log out</Link></footer></form></dialog></template>
<style scoped>
